Here's a simple Node.js Express application that implements the two endpoints for adding items to a shopping cart and retrieving its contents:

```javascript
const express = require('express');
const app = express();
const port = 3000;

app.use(express.json());

let shoppingCart = [];

// Generate unique ID for each item in the cart
function generateUniqueId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

// Add an item to the shopping cart
app.post('/cart/add', (req, res) => {
  const { name, price, quantity } = req.body;

  if (!name || !price || !quantity) {
    return res.status(400).json({ message: 'Missing required fields: name, price, or quantity.' });
  }

  const newItem = {
    id: generateUniqueId(),
    name,
    price,
    quantity
  };

  shoppingCart.push(newItem);

  res.status(201).json(newItem);
});

// Get the current contents of the shopping cart
app.get('/cart', (req, res) => {
  res.json(shoppingCart);
});

app.listen(port, () => {
  console.log(`Shopping cart app listening at http://localhost:${port}`);
});
```

To run this application, make sure you have Node.js installed and follow these steps:

1. Create a new directory for your project.
2. Run `npm init -y` inside the directory to create a package.json file.
3. Install Express by running `npm install express`.
4. Save the code above as `index.js` in your project directory.
5. Start the server by running `node index.js`.

You can now use tools like Postman or curl to test the `/cart/add` and `/cart` endpoints.

Example request to add an item to the cart:
```
POST http://localhost:3000/cart/add
Content-Type: application/json

{
  "name": "Apple",
  "price": 1.5,
  "quantity": 3
}
```

Example request to get the current contents of the cart:
```
GET http://localhost:3000/cart
```

# **Frontend Architecture for WebLLM Applications: React Patterns for Browser-Based Language Models**

## **1.0 Sovereign Architecture Declaration**

This entry establishes a sovereign technical framework for WebLLM applications—browser-hosted language models operating under user computational jurisdiction. Unlike traditional client-server architectures, WebLLM frontends must manage **local computational sovereignty**, **deterministic state flows**, and **resource-aware execution** while maintaining responsive user interfaces.

## **2.0 Core Architectural Principles**

### **2.1 Computational Sovereignty**
WebLLM applications execute entirely within the user's computational environment. This demands:
- **Local Model Isolation**: Each model instance operates in dedicated Web Workers
- **Resource Transparency**: Real-time visibility into memory, CPU, and thermal constraints
- **Graceful Degradation**: Progressive capability reduction under resource constraints

### **2.2 Deterministic State Management**
Language model inference requires predictable state transitions:
```typescript
interface InferenceState {
  phase: 'idle' | 'loading' | 'streaming' | 'complete' | 'error';
  tokens: Array<string>;
  metadata: {
    inferenceTime: number;
    tokensPerSecond: number;
    memoryUsage: MemoryProfile;
  };
  constraints: ResourceConstraints;
}
```

### **2.3 Resource-Aware Execution**
Implement **Computational Budgeting**:
```typescript
class ResourceGovernor {
  private budget: ComputationalBudget;

  allocateForInference(
    modelSize: number, 
    contextLength: number
  ): AllocationResult {
    // Calculate memory and thermal budgets
    return this.calculateSustainableThroughput();
  }
}
```

## **3.0 React Pattern Taxonomy**

### **3.1 Model Worker Abstraction Layer**
```typescript
// Sovereign Worker Bridge Pattern
class ModelWorkerSovereign {
  private worker: Worker;
  private state: WorkerState;

  constructor(modelConfig: ModelManifest) {
    this.worker = this.initializeSovereignWorker(modelConfig);
    this.establishMessageProtocol();
  }

  // Zero-trust message validation
  private validateMessage(message: WorkerMessage): ValidationResult {
    return this.verifyMessageIntegrity(message);
  }
}
```

### **3.2 Streaming Token Architecture**
Implement **Deterministic Token Streaming** with backpressure management:

```typescript
function useTokenStream(
  modelWorker: ModelWorkerSovereign,
  resourceGovernor: ResourceGovernor
) {
  const [tokens, setTokens] = useState<Array<Token>>([]);
  const [streamState, setStreamState] = useState<StreamState>('idle');

  // Token stream with resource awareness
  const streamTokens = useCallback(async (prompt: string) => {
    const allocation = resourceGovernor.allocateForInference();

    if (!allocation.granted) {
      throw new ResourceConstraintError(allocation.reason);
    }

    const tokenStream = modelWorker.createTokenStream(prompt, {
      maxTokens: allocation.maxTokens,
      throttle: allocation.throttleMs
    });

    for await (const token of tokenStream) {
      setTokens(prev => [...prev, token]);

      // Check resource constraints mid-stream
      if (resourceGovernor.isOverBudget()) {
        tokenStream.cancel('Resource budget exceeded');
        break;
      }
    }
  }, [modelWorker, resourceGovernor]);

  return { tokens, streamTokens, streamState };
}
```

### **3.3 Computational Resource Components**
```tsx
// Resource-Aware Inference Component
const ResourceAwareInference: React.FC<InferenceProps> = ({
  model,
  prompt
}) => {
  const resourceGovernor = useResourceGovernor();
  const { tokens, streamTokens } = useTokenStream(model, resourceGovernor);
  const [resourceState, setResourceState] = useState<ResourceState>();

  // Real-time resource monitoring
  useLayoutEffect(() => {
    const monitor = resourceGovernor.createMonitor();
    return monitor.subscribe(setResourceState);
  }, [resourceGovernor]);

  return (
    <SovereignContainer>
      <ResourceDisplay state={resourceState} />
      <TokenStreamVisualizer tokens={tokens} />
      <InferenceControls 
        onStart={() => streamTokens(prompt)}
        disabled={!resourceState?.canStartInference}
      />
    </SovereignContainer>
  );
};
```

## **4.0 State Management Patterns**

### **4.1 Inference State Machine**
Implement a **Deterministic State Machine** for model inference:

```typescript
class InferenceStateMachine {
  private state: InferenceState;
  private transitions: Map<StatePhase, TransitionRule>;

  transition(action: InferenceAction): StateTransition {
    const rule = this.transitions.get(this.state.phase);

    if (!rule?.allowedActions.includes(action.type)) {
      throw new StateTransitionError('Invalid transition');
    }

    // Apply deterministic state update
    const newState = this.applyDeterministicUpdate(
      this.state, 
      action,
      Date.now() // Timestamp for deterministic ordering
    );

    this.state = newState;
    return { from: this.state, to: newState };
  }

  private applyDeterministicUpdate(
    current: InferenceState,
    action: InferenceAction,
    timestamp: number
  ): InferenceState {
    // Deterministic state transformation
    return this.computeNextState(current, action, timestamp);
  }
}
```

### **4.2 Model Cache Strategy**
Implement **Sovereign Model Caching** with integrity verification:

```typescript
class SovereignModelCache {
  private cache: CacheStorage;
  private integrityVerifier: IntegrityVerifier;

  async cacheModel(
    modelId: string, 
    weights: ArrayBuffer,
    manifest: ModelManifest
  ): Promise<CacheResult> {
    // Verify model integrity before caching
    const integrity = await this.integrityVerifier.verify(
      weights, 
      manifest.signature
    );

    if (!integrity.valid) {
      throw new IntegrityError('Model verification failed');
    }

    // Store with metadata
    return this.cache.store(modelId, {
      weights,
      manifest,
      cachedAt: Date.now(),
      accessCount: 0,
      lastVerified: Date.now()
    });
  }
}
```

## **5.0 Performance Optimization Patterns**

### **5.1 Progressive Model Loading**
```typescript
// Progressive Model Initialization Pattern
class ProgressiveModelLoader {
  async loadModel(
    modelManifest: ModelManifest,
    progressCallback: (progress: LoadProgress) => void
  ): Promise<LoadedModel> {
    // Phase 1: Load minimal inference engine
    await this.loadRuntime(progressCallback);

    // Phase 2: Stream model weights with priority
    const weights = await this.streamWeights(
      modelManifest,
      this.getResourceAwarePriority()
    );

    // Phase 3: Initialize with available resources
    return this.initializeModel(weights, {
      memoryLimit: this.getAvailableMemory() * 0.8
    });
  }
}
```

### **5.2 Computational Scheduling**
Implement **Fair Resource Scheduling** across multiple inference tasks:

```typescript
class InferenceScheduler {
  private queue: PriorityQueue<InferenceTask>;
  private activeTasks: Set<InferenceTask>;

  schedule(task: InferenceTask): SchedulingTicket {
    // Calculate priority based on resource requirements
    const priority = this.calculatePriority(
      task.resourceRequirements,
      this.getAvailableResources()
    );

    this.queue.enqueue(task, priority);

    return {
      ticketId: generateDeterministicId(task),
      estimatedStart: this.estimateStartTime(priority),
      priority
    };
  }
}
```

## **6.0 Error Boundary and Recovery Patterns**

### **6.1 Resource Exhaustion Recovery**
```tsx
// Resource-Aware Error Boundary
class ResourceErrorBoundary extends React.Component {
  state = { hasError: false, errorType: null };

  static getDerivedStateFromError(error: Error) {
    return {
      hasError: true,
      errorType: this.classifyError(error)
    };
  }

  private classifyError(error: Error): ErrorClassification {
    if (error instanceof MemoryExhaustionError) {
      return 'memory';
    } else if (error instanceof ThermalThrottleError) {
      return 'thermal';
    } else if (error instanceof ModelIntegrityError) {
      return 'integrity';
    }
    return 'unknown';
  }

  render() {
    if (this.state.hasError) {
      return (
        <RecoveryInterface 
          errorType={this.state.errorType}
          onRecover={this.handleRecovery}
          availableActions={this.getRecoveryActions()}
        />
      );
    }

    return this.props.children;
  }
}
```

### **6.2 Graceful Degradation Protocol**
```typescript
interface DegradationStrategy {
  level: 'none' | 'reduced' | 'minimal' | 'offline';
  actions: Array<DegradationAction>;
  conditions: ResourceCondition[];
}

class GracefulDegradationManager {
  private strategies: Map<ResourceCondition, DegradationStrategy>;

  getCurrentStrategy(): DegradationStrategy {
    const conditions = this.monitor.getCurrentConditions();

    // Find matching strategy with highest priority
    return this.findMatchingStrategy(conditions);
  }

  applyStrategy(strategy: DegradationStrategy): AppliedActions {
    // Apply degradation actions deterministically
    return strategy.actions.map(action => 
      this.applyDegradationAction(action)
    );
  }
}
```

## **7.0 Testing and Verification Patterns**

### **7.1 Deterministic Testing**
```typescript
// Deterministic Inference Test
describe('InferenceStateMachine', () => {
  test('produces identical state given same inputs', () => {
    const machine = new InferenceStateMachine();
    const timestamp = 1234567890;

    const result1 = machine.transition(
      { type: 'START_INFERENCE', prompt: 'Test', timestamp }
    );

    // Reset and replay
    machine.reset();

    const result2 = machine.transition(
      { type: 'START_INFERENCE', prompt: 'Test', timestamp }
    );

    expect(result1).toEqual(result2); // Deterministic equality
